using AutoMapper;
using ProductManagement.Common.Mapping.Resolvers;
using ProductManagement.Features;
using ProductManagement.Features.DTOs;
using ProductManagement.Features.Request;

namespace ProductManagement.Common.Mapping;

public class AdvancedProductMappingProfile : Profile
{
    public AdvancedProductMappingProfile()
    {
        CreateMap<Product, CreateProductProfileRequest>();

        CreateMap<CreateProductProfileRequest, Product>()
            .ForMember(dest => dest.Id, opt => opt.Ignore())
            .ForMember(dest => dest.Name, opt => opt.MapFrom(src => src.Name))
            .ForMember(dest => dest.Brand, opt => opt.MapFrom(src => src.Brand))
            .ForMember(dest => dest.SKU, opt => opt.MapFrom(src => src.SKU))
            .ForMember(dest => dest.Category, opt => opt.MapFrom(src => src.Category))
            .ForMember(dest => dest.Price, opt => opt.MapFrom(src => src.Category == ProductCategory.Home ? (src.Price * 0.9m) : src.Price ))
            .ForMember(dest => dest.ReleaseDate, opt => opt.MapFrom(src => src.ReleaseDate))
            .ForMember(dest => dest.ImageUrl, opt => opt.MapFrom(src =>  src.Category == ProductCategory.Home ? null : src.ImageUrl))
            .ForMember(dest => dest.StockQuantity, opt => opt.MapFrom(src => src.StockQuantity))
            .ForMember(dest => dest.IsAvailable, opt => opt.MapFrom(src => src.StockQuantity > 0))
            .ForMember(dest => dest.CreatedAt, opt => opt.MapFrom(_ => DateTime.UtcNow))
            .ForMember(dest => dest.UpdatedAt, opt => opt.MapFrom(_ => DateTime.UtcNow));

        CreateMap<Product, ProductProfileDto>()
            .ForMember(dest => dest.CategoryDisplayName, opt => opt.MapFrom<CategoryDisplayResolver>())
            .ForMember(dest => dest.FormattedPrice, opt => opt.MapFrom<PriceFormatterResolver>())
            .ForMember(dest => dest.ProductAge, opt => opt.MapFrom<ProductAgeResolver>())
            .ForMember(dest => dest.BrandInitials, opt => opt.MapFrom<BrandInitialsResolver>())
            .ForMember(dest => dest.AvailabilityStatus, opt => opt.MapFrom<AvailabilityStatusResolver>());
    }
}

using AutoMapper;
using ProductManagement.Common.Mapping.Resolvers;
using ProductManagement.Features;
using ProductManagement.Features.DTOs;
using ProductManagement.Features.Request;

namespace ProductManagement.Common.Mapping;

public class AdvancedProductMappingProfile : Profile
{
    public AdvancedProductMappingProfile()
    {
        CreateMap<Product, CreateProductProfileRequest>();

        CreateMap<CreateProductProfileRequest, Product>()
            .ForMember(dest => dest.Id, opt => opt.MapFrom(_ => Guid.NewGuid()))
            .ForMember(dest => dest.Name, opt => opt.MapFrom(src => src.Name))
            .ForMember(dest => dest.Brand, opt => opt.MapFrom(src => src.Brand))
            .ForMember(dest => dest.SKU, opt => opt.MapFrom(src => src.SKU))
            .ForMember(dest => dest.Category, opt => opt.MapFrom(src => src.Category))
            .ForMember(dest => dest.Price, opt => opt.MapFrom(src => src.Category == ProductCategory.Home ? (src.Price * 0.9m) : src.Price ))
            .ForMember(dest => dest.ReleaseDate, opt => opt.MapFrom(src => src.ReleaseDate))
            .ForMember(dest => dest.ImageUrl, opt => opt.MapFrom(src =>  src.Category == ProductCategory.Home ? null : src.ImageUrl))
            .ForMember(dest => dest.StockQuantity, opt => opt.MapFrom(src => src.StockQuantity))
            .ForMember(dest => dest.IsAvailable, opt => opt.MapFrom(src => src.StockQuantity > 0))
            .ForMember(dest => dest.CreatedAt, opt => opt.MapFrom(_ => DateTime.UtcNow))
            .ForMember(dest => dest.UpdatedAt, opt => opt.Ignore());

        CreateMap<Product, ProductProfileDto>()
            .ForMember(dest => dest.CategoryDisplayName, opt => opt.MapFrom<CategoryDisplayResolver>())
            .ForMember(dest => dest.FormattedPrice, opt => opt.MapFrom<PriceFormatterResolver>())
            .ForMember(dest => dest.ProductAge, opt => opt.MapFrom<ProductAgeResolver>())
            .ForMember(dest => dest.BrandInitials, opt => opt.MapFrom<BrandInitialsResolver>())
            .ForMember(dest => dest.AvailabilityStatus, opt => opt.MapFrom<AvailabilityStatusResolver>());
    }
}

using AutoMapper;
using ProductManagement.Features.Product;
using ProductManagement.Features.Product.DTOs;

namespace ProductManagement.Common.Mapping.Resolvers;

// Deprecated: AvailabilityStatusResolver moved into AdvanceProductMappingProfile as a private static function.
// File retained for history; safe to delete if desired.
public class AvailabilityStatusResolver : IValueResolver<Product, ProductProfileDTO, string>
{
    public string Resolve(Product source, ProductProfileDTO destination, string destMember, ResolutionContext context)
    {
        return source.IsAvaliable ? "Available" : "Unavailable";
    }
}

using AutoMapper;
using ProductManagement.Features.Product;
using ProductManagement.Features.Product.DTOs;
using System.Globalization;

namespace ProductManagement.Common.Mapping.Resolvers;

// Deprecated: PriceFormatterResolver moved into AdvanceProductMappingProfile as a private static function.
// File retained for history; safe to delete if you prefer.
public class PriceFormatterResolver : IValueResolver<Product, ProductProfileDTO, string>
{
    public string Resolve(Product source, ProductProfileDTO destination, string destMember, ResolutionContext context)
    {
        return source.Price.ToString("C", CultureInfo.CurrentCulture);
    }
}

using AutoMapper;
using ProductManagement.Features.Product;
using ProductManagement.Features.Product.DTOs;

namespace ProductManagement.Common.Mapping.Resolvers;

// Deprecated: ProductAgeResolver moved into AdvanceProductMappingProfile as a private static function.
// File retained for history; safe to delete if desired.
public class ProductAgeResolver : IValueResolver<Product, ProductProfileDTO, string>
{
    public string Resolve(Product source, ProductProfileDTO destination, string destMember, ResolutionContext context)
    {
        var days = (DateTime.UtcNow - source.ReleaseDate).Days;
        return days switch
        {
            < 0 => "Not released",
            0 => "New",
            1 => "1 day",
            _ => $"{days} days"
        };
    }
}

